Consider the following recursive program-

int mysteryX(int *a, int i, int j, int P) {
    if (i >= j) {
        return i;
    } else if (a[i] < P) {
        return mysteryX(a, i + 1, j, P);
    } else if (a[j] > P) {
        return mysteryX(a, i, j - 1, P);
    } else {
        int temp = a[i];
        a[i] = a[j];
        a[j] = temp;
        return mysteryX(a, i + 1, j - 1, P);
    }
}
