The following function operates on a linked list of Node objects, which is represented by a pointer
called head that points to the first node in the list. The function is recursive in nature.

Node* mystryrecur(Node* head, int x)
{
   if (head == NULL)
       return NULL;

   if (head → data == x)
   {
       Node* tmp = head → next;
       free(head);
       return mystryrecur(tmp, x);;
   }
   else
   {
       head → next = mystryrecur(head → next, x);
       return head;
   }
}

